-- S2A synthetic integration harness. AUTHORING ONLY until a disposable target is authorized.
-- Run the reviewed migration separately in an explicitly approved empty disposable database.
-- The caller must set session context KVK_S2A_AUTHORIZED_SERVER and KVK_S2A_AUTHORIZED_DATABASE
-- to that exact approved server/database, and KVK_S2A_DISPOSABLE_AUTHORIZED to integer 1.
-- No targets are supplied here; no SQLCMD substitutions, guessed hosts, USE, or connection defaults.
-- Disposable database name must start K98_S2A_Disposable_ (literal underscores).
-- This is a fixture rollback, not migration rollback. It cannot prove concurrent DAL locking,
-- commit-time completeness, immutable-write policy, parser admission or restart behavior.
SET NOCOUNT ON;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
IF @@TRANCOUNT <> 0
    THROW 51100, 'Constraint harness refuses an ambient transaction.', 1;
IF TRY_CONVERT(int, SESSION_CONTEXT(N'KVK_S2A_DISPOSABLE_AUTHORIZED')) IS NULL
   OR TRY_CONVERT(int, SESSION_CONTEXT(N'KVK_S2A_DISPOSABLE_AUTHORIZED')) <> 1
   OR CONVERT(nvarchar(128), SESSION_CONTEXT(N'KVK_S2A_AUTHORIZED_SERVER')) IS NULL
   OR CONVERT(nvarchar(128), SESSION_CONTEXT(N'KVK_S2A_AUTHORIZED_DATABASE')) IS NULL
   OR CONVERT(nvarchar(128), SESSION_CONTEXT(N'KVK_S2A_AUTHORIZED_SERVER')) COLLATE Latin1_General_100_BIN2 <> CONVERT(nvarchar(128), SERVERPROPERTY('ServerName')) COLLATE Latin1_General_100_BIN2
   OR CONVERT(nvarchar(128), SESSION_CONTEXT(N'KVK_S2A_AUTHORIZED_DATABASE')) COLLATE Latin1_General_100_BIN2 <> DB_NAME() COLLATE Latin1_General_100_BIN2
   OR DB_ID() <= 4 OR DB_NAME() NOT LIKE N'K98[_]S2A[_]Disposable[_]%'
    THROW 51100, 'Explicit authorization for this exact disposable server/database is required.', 1;

-- FK/check violations must remain recoverable at a savepoint in this test-only transaction.
-- Production DAL transaction policy is separate. Restore caller settings at the end.
DECLARE @WasXactAbort bit = CASE WHEN (16384 & @@OPTIONS) = 16384 THEN 1 ELSE 0 END;
DECLARE @WasRoundAbort bit = CASE WHEN (8192 & @@OPTIONS) = 8192 THEN 1 ELSE 0 END;
SET XACT_ABORT OFF;
SET NUMERIC_ROUNDABORT OFF;
DECLARE @obs uniqueidentifier = NEWID(), @obs2 uniqueidentifier = NEWID();
DECLARE @rev uniqueidentifier = NEWID(), @rev2 uniqueidentifier = NEWID();
DECLARE @report uniqueidentifier = NEWID(), @report2 uniqueidentifier = NEWID();
DECLARE @agg uniqueidentifier = NEWID(), @agg2 uniqueidentifier = NEWID();
DECLARE @roster uniqueidentifier = NEWID(), @attempt uniqueidentifier = NEWID();
DECLARE @hash binary(32) = HASHBYTES('SHA2_256', CONVERT(varbinary(16), NEWID()));
DECLARE @hash2 binary(32) = HASHBYTES('SHA2_256', CONVERT(varbinary(16), NEWID()));
DECLARE @utc datetime2(0) = '2000-01-01T00:00:00', @season int = 2147483600;
DECLARE @Passed int = 0;
BEGIN TRY
    BEGIN TRANSACTION;
    -- Refuse collisions rather than using or deleting any pre-existing source rows.
    IF EXISTS (SELECT 1 FROM KVK.SourceObservation WHERE KVK_NO = @season)
       OR EXISTS (SELECT 1 FROM KVK.SourceAggregateReport WHERE KVK_NO = @season)
        THROW 51100, 'Synthetic season already occupied; use an empty disposable target.', 1;

-- Valid graph across all twelve tables, including bigint extrema, genuine zero and unavailable B0.
INSERT KVK.SourceArtifact (ArtifactHash, ByteCount, StorageKey, CreatedUTC) VALUES (@hash, 100, LOWER(CONVERT(varchar(64), @hash, 2)) + N'.xlsx', @utc);
INSERT KVK.SourceObservation (ObservationID, SourceKey, KVK_NO, ScanStartUTC, TimePrecision, EventDiscriminator, SelectedRevisionID, SelectionVersion) VALUES (@obs, 'snapshot_report_v1', @season, @utc, 'minute', N'main', NULL, 1);
