INSERT KVK.SourceRosterMember (RosterID, SourceKey, KVK_NO, GovernorID, b0_kingdom, b0_power) VALUES (@roster, 'snapshot_report_v1', @season, 9223372036854775807, 1, NULL);
INSERT KVK.SourceAggregateReport (ReportID, SourceKey, KVK_NO, PeriodKey, PeriodKind, SelectedRevisionID, SelectionVersion) VALUES (@report, 'snapshot_report_v1', @season, 'fight:synthetic', 'fight', NULL, 1);
