UPDATE KVK.SourceObservation SET SelectedRevisionID = @rev WHERE ObservationID = @obs;
UPDATE KVK.SourceAggregateReport SET SelectedRevisionID = @agg WHERE ReportID = @report;

-- Equivalent bytes can have a separate artifact/attempt while retaining the exact revision/scan.
INSERT KVK.SourceArtifact (ArtifactHash, ByteCount, StorageKey, CreatedUTC) VALUES (@hash2, 100, LOWER(CONVERT(varchar(64), @hash2, 2)) + N'.xlsx', @utc);
INSERT KVK.SourceImportAttempt (AttemptID, SourceKey, KVK_NO, GuildID, MessageID, AttachmentID, ActionKey, ArtifactHash, ActorID, ChannelID, OriginalFilename, ReceivedUTC, Status, DiagnosticSummary, ObservationRevisionID, ProvenanceJson) VALUES (NEWID(), 'snapshot_report_v1', @season, 'synthetic-guild', 'synthetic-message', 'synthetic-reexport', 'accept', @hash2, N'synthetic-operator', 'synthetic-channel', N'synthetic.xlsx', @utc, 'duplicate', N'fixture accepted', @rev, N'{}');
IF (SELECT COUNT(*) FROM KVK.SourceLogicalScan WHERE KVK_NO = @season) <> 1
    THROW 51100, 'Alias or aggregate allocated a player scan.', 1;
IF (SELECT COUNT(*) FROM KVK.SourceObservationRevision WHERE ObservationID = @obs) <> 1
    THROW 51100, 'Alias allocated another observation revision.', 1;
-- A finalization event may pin unchanged aggregate content; its hash must not suppress finality.
INSERT KVK.SourceAggregateRevision (RevisionID, SourceKey, KVK_NO, ReportID, PeriodKind, RevisionNo, ArtifactHash, SemanticHash, DigestVersion, SchemaVersion, ScanStartUTC, TimePrecision, CoverageStartUTC, CoverageEndUTC, AsOfUTC, ReportState, AcceptedUTC, AcceptedBy, Reason, MappingDigest, ScopeDigest, MetadataJson, SupersedesRevisionID) VALUES (NEWID(), 'snapshot_report_v1', @season, @report, 'fight', 2, @hash, @hash, 'semantic_digest_v1', 'snapshot_report_aggregate_v1', @utc, 'minute', @utc, @utc, @utc, 'final', @utc, N'synthetic-operator', N'synthetic fixture', @hash, @hash, N'{}', @agg);

