INSERT @Cases (Label, Statement, ExpectedError, ExpectedConstraint) VALUES (N'noncanonical field status Available', N'UPDATE KVK.SourcePlayerSnapshot SET FieldStatusJson = JSON_MODIFY(FieldStatusJson, ''$.power'', ''Available'') WHERE RevisionID = @rev;', 547, N'CK_SourcePlayerSnapshot_power');
INSERT @Cases (Label, Statement, ExpectedError, ExpectedConstraint) VALUES (N'noncanonical field status Invalid_source_value', N'UPDATE KVK.SourcePlayerSnapshot SET FieldStatusJson = JSON_MODIFY(FieldStatusJson, ''$.city_hall'', ''Invalid_source_value'') WHERE RevisionID = @rev;', 547, N'CK_SourcePlayerSnapshot_city_hall');
INSERT @Cases (Label, Statement, ExpectedError, ExpectedConstraint) VALUES (N'noncanonical field status Unsupported', N'UPDATE KVK.SourcePlayerSnapshot SET FieldStatusJson = JSON_MODIFY(FieldStatusJson, ''$.city_hall'', ''Unsupported'') WHERE RevisionID = @rev;', 547, N'CK_SourcePlayerSnapshot_city_hall');
INSERT @Cases (Label, Statement, ExpectedError, ExpectedConstraint) VALUES (N'noncanonical field status Not_applicable', N'UPDATE KVK.SourcePlayerSnapshot SET FieldStatusJson = JSON_MODIFY(FieldStatusJson, ''$.city_hall'', ''Not_applicable'') WHERE RevisionID = @rev;', 547, N'CK_SourcePlayerSnapshot_city_hall');
INSERT @Cases (Label, Statement, ExpectedError, ExpectedConstraint) VALUES (N'corrected observation requires predecessor', N'UPDATE KVK.SourceObservationRevision SET AcceptanceState = ''corrected'', SupersedesRevisionID = NULL WHERE RevisionID = @rev;', 547, N'CK_SourceObservationRevision_State');

DECLARE @CaseNo int = 1, @Label nvarchar(128), @Statement nvarchar(max), @ExpectedError int, @ExpectedConstraint nvarchar(128);
DECLARE @Rejected bit, @ActualError int, @ActualMessage nvarchar(4000);
WHILE @CaseNo <= (SELECT MAX(CaseNo) FROM @Cases)
BEGIN
    SELECT @Label = Label, @Statement = Statement, @ExpectedError = ExpectedError, @ExpectedConstraint = ExpectedConstraint FROM @Cases WHERE CaseNo = @CaseNo;
    SET @Rejected = 0;
    SAVE TRANSACTION RejectionCase;
    BEGIN TRY
        EXEC sys.sp_executesql @Statement,
          N'@obs uniqueidentifier,@obs2 uniqueidentifier,@rev uniqueidentifier,@rev2 uniqueidentifier,@report uniqueidentifier,@report2 uniqueidentifier,@agg uniqueidentifier,@agg2 uniqueidentifier,@roster uniqueidentifier,@attempt uniqueidentifier,@hash binary(32),@hash2 binary(32),@utc datetime2(0),@season int',
          @obs,@obs2,@rev,@rev2,@report,@report2,@agg,@agg2,@roster,@attempt,@hash,@hash2,@utc,@season;
    END TRY
    BEGIN CATCH
        SET @ActualError = ERROR_NUMBER(); SET @ActualMessage = ERROR_MESSAGE();
        IF @ActualError <> @ExpectedError OR (@ExpectedConstraint <> N'' AND CHARINDEX(@ExpectedConstraint, @ActualMessage) = 0)
        BEGIN
            PRINT @Label;
            THROW;
        END;
        IF XACT_STATE() <> 1 THROW 51100, 'Expected rejection doomed the fixture transaction.', 1;
        SET @Rejected = 1;
    END CATCH;
    ROLLBACK TRANSACTION RejectionCase;
    IF @Rejected = 0
    BEGIN
        PRINT @Label;
        THROW 51100, 'Expected constraint rejection did not occur.', 1;
    END;
    SET @Passed += 1;
    SET @CaseNo += 1;
END;

-- Canonical enum tokens remain valid with the case-sensitive JSON value collation.
SAVE TRANSACTION CanonicalStates;
UPDATE KVK.SourcePlayerSnapshot SET city_hall = NULL, FieldStatusJson = JSON_MODIFY(FieldStatusJson, '$.city_hall', 'unsupported') WHERE RevisionID = @rev;
UPDATE KVK.SourcePlayerSnapshot SET FieldStatusJson = JSON_MODIFY(FieldStatusJson, '$.city_hall', 'not_applicable') WHERE RevisionID = @rev;
ROLLBACK TRANSACTION CanonicalStates;
-- A corrected revision with a same-observation predecessor is accepted; undo it after proof.
SAVE TRANSACTION CorrectedLineage;
DECLARE @correction uniqueidentifier = NEWID();
INSERT KVK.SourceObservationRevision (RevisionID, SourceKey, KVK_NO, ObservationID, RevisionNo, SemanticHash, DigestVersion, SchemaVersion, ArtifactHash, SupersedesRevisionID, AcceptanceState, AcceptedUTC, AcceptedBy, Reason, MetadataJson)
VALUES (@correction, 'snapshot_report_v1', @season, @obs, 99, @hash2, 'semantic_digest_v1', 'snapshot_report_players_v1', @hash, @rev, 'corrected', @utc, N'synthetic-operator', N'correction with predecessor', N'{}');
IF NOT EXISTS (SELECT 1 FROM KVK.SourceObservationRevision WHERE RevisionID = @correction AND SupersedesRevisionID = @rev AND AcceptanceState = 'corrected')
    THROW 51100, 'Valid correction lineage was not stored.', 1;
ROLLBACK TRANSACTION CorrectedLineage;

-- Exact decimal boundary and raw/unit precision survive storage without binary float.
UPDATE KVK.SourceCampReportRow SET dkp = 99999999999999999999999999999999.999999 WHERE RevisionID = @agg;
IF NOT EXISTS (SELECT 1 FROM KVK.SourceCampReportRow WHERE RevisionID = @agg AND dkp = 99999999999999999999999999999999.999999 AND t4_kills_raw = N'25.3M' AND t4_kills_unit = 100000)
    THROW 51100, 'Exact aggregate precision did not survive storage.', 1;
-- T46 simulation: failure after only kingdom rows, before camp rows, rolls back the candidate.
SAVE TRANSACTION PartialAggregate;
INSERT KVK.SourceAggregateRevision (RevisionID, SourceKey, KVK_NO, ReportID, PeriodKind, RevisionNo, ArtifactHash, SemanticHash, DigestVersion, SchemaVersion, ScanStartUTC, TimePrecision, CoverageStartUTC, CoverageEndUTC, AsOfUTC, ReportState, AcceptedUTC, AcceptedBy, Reason, MappingDigest, ScopeDigest, MetadataJson) VALUES (@rev2, 'snapshot_report_v1', @season, @report, 'fight', 3, @hash, @hash, 'semantic_digest_v1', 'snapshot_report_aggregate_v1', @utc, 'minute', @utc, @utc, @utc, 'live', @utc, N'synthetic-operator', N'synthetic fixture', @hash, @hash, N'{}');
INSERT KVK.SourceKingdomReportRow (RevisionID, SourceKey, KVK_NO, Kingdom, CampID, CampLabel, MappingDigest, t4_kills, t4_kills_raw, t4_kills_unit, t4_kills_precision, t5_kills, t5_kills_raw, t5_kills_unit, t5_kills_precision, kp_t4_t5, kp_t4_t5_raw, kp_t4_t5_unit, kp_t4_t5_precision, dead, dead_raw, dead_unit, dead_precision, t4_t5_dead, t4_t5_dead_raw, t4_t5_dead_unit, t4_t5_dead_precision, healed, healed_raw, healed_unit, healed_precision, acclaim, acclaim_raw, acclaim_unit, acclaim_precision, dkp, dkp_raw, dkp_unit, dkp_precision, RawCellsJson) VALUES (@rev2, 'snapshot_report_v1', @season, 1, 1, N'Synthetic camp', @hash, 25300000, N'25.3M', 100000, 'reported_abbreviated', 25300000, N'25.3M', 100000, 'reported_abbreviated', 25300000, N'25.3M', 100000, 'reported_abbreviated', 25300000, N'25.3M', 100000, 'reported_abbreviated', 25300000, N'25.3M', 100000, 'reported_abbreviated', 25300000, N'25.3M', 100000, 'reported_abbreviated', 25300000, N'25.3M', 100000, 'reported_abbreviated', 25300000, N'25.3M', 100000, 'reported_abbreviated', N'{}');
ROLLBACK TRANSACTION PartialAggregate;
IF EXISTS (SELECT 1 FROM KVK.SourceAggregateRevision WHERE RevisionID = @rev2)
   OR EXISTS (SELECT 1 FROM KVK.SourceKingdomReportRow WHERE RevisionID = @rev2)
   OR EXISTS (SELECT 1 FROM KVK.SourceCampReportRow WHERE RevisionID = @rev2)
   OR NOT EXISTS (SELECT 1 FROM KVK.SourceAggregateReport WHERE ReportID = @report AND SelectedRevisionID = @agg)
    THROW 51100, 'Half aggregate survived rollback or changed selection.', 1;

ROLLBACK TRANSACTION;
IF @@TRANCOUNT <> 0 THROW 51100, 'Fixture transaction remained open.', 1;
IF EXISTS (SELECT 1 FROM KVK.SourceArtifact WHERE ArtifactHash IN (@hash, @hash2))
    THROW 51100, 'Synthetic rows survived rollback: SourceArtifact.', 1;
IF EXISTS (SELECT 1 FROM KVK.SourceImportAttempt WHERE ArtifactHash IN (@hash, @hash2))
    THROW 51100, 'Synthetic rows survived rollback: SourceImportAttempt.', 1;
IF EXISTS (SELECT 1 FROM KVK.SourceObservation WHERE ObservationID IN (@obs, @obs2))
    THROW 51100, 'Synthetic rows survived rollback: SourceObservation.', 1;
IF EXISTS (SELECT 1 FROM KVK.SourceObservationRevision WHERE RevisionID IN (@rev, @rev2))
    THROW 51100, 'Synthetic rows survived rollback: SourceObservationRevision.', 1;
IF EXISTS (SELECT 1 FROM KVK.SourcePlayerSnapshot WHERE RevisionID IN (@rev))
    THROW 51100, 'Synthetic rows survived rollback: SourcePlayerSnapshot.', 1;
IF EXISTS (SELECT 1 FROM KVK.SourceLogicalScan WHERE ObservationID IN (@obs, @obs2))
    THROW 51100, 'Synthetic rows survived rollback: SourceLogicalScan.', 1;
IF EXISTS (SELECT 1 FROM KVK.SourceRoster WHERE RosterID IN (@roster))
    THROW 51100, 'Synthetic rows survived rollback: SourceRoster.', 1;
IF EXISTS (SELECT 1 FROM KVK.SourceRosterMember WHERE RosterID IN (@roster))
    THROW 51100, 'Synthetic rows survived rollback: SourceRosterMember.', 1;
IF EXISTS (SELECT 1 FROM KVK.SourceAggregateReport WHERE ReportID IN (@report, @report2))
    THROW 51100, 'Synthetic rows survived rollback: SourceAggregateReport.', 1;
IF EXISTS (SELECT 1 FROM KVK.SourceAggregateRevision WHERE ReportID IN (@report, @report2))
    THROW 51100, 'Synthetic rows survived rollback: SourceAggregateRevision.', 1;
IF EXISTS (SELECT 1 FROM KVK.SourceKingdomReportRow WHERE RevisionID IN (@agg, @rev2))
    THROW 51100, 'Synthetic rows survived rollback: SourceKingdomReportRow.', 1;
IF EXISTS (SELECT 1 FROM KVK.SourceCampReportRow WHERE RevisionID IN (@agg, @rev2))
    THROW 51100, 'Synthetic rows survived rollback: SourceCampReportRow.', 1;
IF @WasXactAbort = 1 SET XACT_ABORT ON;
IF @WasRoundAbort = 1 SET NUMERIC_ROUNDABORT ON;
SELECT @Passed AS ExpectedRejectionsPassed, 12 AS TablesCheckedForRollback, N'ROLLBACK verified; concurrency/DAL integration not tested' AS Outcome;
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
    IF @WasXactAbort = 1 SET XACT_ABORT ON;
    IF @WasRoundAbort = 1 SET NUMERIC_ROUNDABORT ON;
    THROW;
END CATCH;
